-- ~/.config/nvim/lsp/lua_ls.lua

return {
	cmd = { "lua-language-server" },
	filetypes = { "lua" },
	root_markers = {
		".luarc.json", ".luarc.jsonc", ".luacheckrc",
		".stylua.toml", "stylua.toml", "selene.toml", "selene.yml", ".git",
	},
	settings = {
		Lua = {
			runtime = { version = "LuaJIT" },
			diagnostics = { globals = { "vim", "hl" } },
			workspace = {
				checkThirdParty = false,
				library = {
					vim.env.VIMRUNTIME,
					-- Hyprland's autogenerated Lua stubs: this is what gives
					-- completion and type checking for the whole `hl` API and
					-- settles the field names by hand-checking rather than guessing.
					"/usr/share/hypr/stubs",
				},
			},
			telemetry = { enable = false },
			format = { enable = false },
		},
	},
}
